function Pe([string]$p){[byte[]]$b=[IO.File]::ReadAllBytes($p);if($b.Length-lt512-or$b[0]-ne0x4d-or$b[1]-ne0x5a){throw "Invalid MZ: $p"};$o=[BitConverter]::ToInt32($b,0x3c);if($o-lt0-or$o+96-ge$b.Length-or$b[$o]-ne0x50-or$b[$o+1]-ne0x45){throw "Invalid/truncated PE: $p"};$opt=$o+24;[pscustomobject]@{Machine=[BitConverter]::ToUInt16($b,$o+4);Magic=[BitConverter]::ToUInt16($b,$opt);Entry=[BitConverter]::ToUInt32($b,$opt+16);Subsystem=[BitConverter]::ToUInt16($b,$opt+68)}}
$ei=Pe $exe;$di=Pe $dll;$ti=Pe $tool;foreach($x in @(@('EXE',$ei),@('PLUGIN',$di),@('SCS_TOOL',$ti))){if($x[1].Magic-ne0x20b-or$x[1].Machine-ne0x8664-or$x[1].Entry-eq0){throw "$($x[0]) is not valid AMD64 PE32+"}};if($ei.Subsystem-ne2){throw 'GUI subsystem is not Windows GUI.'}
