$sumPath=Join-Path $zipPkg 'SHA256SUMS.txt';$sumLines=@(Get-Content $sumPath -Encoding ASCII|Where-Object{$_ -ne ''});$seen=@{}
foreach($line in $sumLines){if($line-notmatch'^([0-9a-f]{64})  (.+)$'){throw "Malformed ZIP SHA256SUMS line: $line"};$expected=$matches[1];$rel=$matches[2].Replace('/','\');if($seen.ContainsKey($rel)){throw "Duplicate ZIP SHA entry: $rel"};$seen[$rel]=$true;$file=Join-Path $zipPkg $rel;if(-not(Test-Path $file)){throw "ZIP SHA target missing: $rel"};$actualHash=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();if($actualHash-ne$expected){throw "ZIP SHA mismatch for $rel expected=$expected actual=$actualHash"}}
foreach($rel in @('ETS2TruckVisualIdentifier.exe','README.txt','THIRD_PARTY_NOTICES.md','Runtime\ets2_truck_visual_identifier.dll','Runtime\scs_tool.exe')){if(-not$seen.ContainsKey($rel)){throw "ZIP SHA manifest missing: $rel"}};if($seen.Count-ne5){throw "Unexpected ZIP SHA manifest count: $($seen.Count)"}
